# ==============================================================================
# Human dlPFC snRNA-seq Step 2: Harmony Integration, Clustering, and Markers
# ------------------------------------------------------------------------------
# Purpose:
#   Integrate post-QC human dlPFC single-nucleus RNA-seq data, perform Harmony
#   batch correction, UMAP embedding, Louvain clustering, and cluster marker
#   discovery. This script is designed as a publication-ready and reproducible
#   version of the validated human Step 2 pipeline.
#
# Input:
#   The QC-filtered merged object generated by Step 1.
#
# Main outputs:
#   BATIUK_OUTPUT_DIR/2-harmony_ALL/res_0.8/
#     dim_35_res_0.8.harmony.rds
#     dim_35_res_0.8.harmony.umap.pdf
#     dim_35_res_0.8.harmony.DE_marker.rds
#     dim_35_res_0.8.harmony.markers.xlsx
#     dim_35_res_0.8.harmony.top50.xlsx
#     dim_35_res_0.8.harmony.top50.csv
#     ALL_harmony_final.rds
#
# Environment:
#   R >= 4.0, Seurat v4, harmony, ggplot2, gridExtra, dplyr, openxlsx
# ===============================================================================


suppressPackageStartupMessages({
  library(Seurat)
  library(harmony)
  library(ggplot2)
  library(gridExtra)
  library(dplyr)
  library(openxlsx)
})

options(stringsAsFactors = FALSE)
set.seed(123)

# ------------------------------------------------------------------------------
# 1. Configuration
# ------------------------------------------------------------------------------
reproduce_dir <- Sys.getenv("BATIUK_OUTPUT_DIR", unset = "")
if (!nzchar(reproduce_dir)) {
  stop("BATIUK_OUTPUT_DIR must be set.", call. = FALSE)
}
GROUP_name    <- "ALL"

# QC-clean merged object generated by Step 1.
premerged_rds <- Sys.getenv(
  "SEURAT_RDS_PATH",
  unset = file.path(reproduce_dir, "human_all_samples_merged.clean.rds")
)

# Core analysis parameters. Keep these unchanged for downstream compatibility.
n_features  <- 2000
n_dims_vec  <- c(35)
resolutions <- c(0.8)
max_dims    <- max(n_dims_vec)

# Output directory. The path is kept identical to the original pipeline.
results_dir <- file.path(
  reproduce_dir,
  paste0("2-harmony_", GROUP_name),
  paste0("res_", paste(resolutions, collapse = "_"))
)
dir.create(results_dir, recursive = TRUE, showWarnings = FALSE)

# ------------------------------------------------------------------------------
# 2. Helper functions
# ------------------------------------------------------------------------------
message_time <- function(...) {
  message(format(Sys.time(), "[%Y-%m-%d %H:%M:%S] "), ...)
}

safe_save_rds <- function(object, file) {
  dir.create(dirname(file), recursive = TRUE, showWarnings = FALSE)
  saveRDS(object, file = file)
  message_time("Saved RDS: ", file)
  invisible(file)
}

safe_ggsave <- function(file, plot, width, height, units = "cm") {
  dir.create(dirname(file), recursive = TRUE, showWarnings = FALSE)
  ggplot2::ggsave(
    filename = file,
    plot     = plot,
    width    = width,
    height   = height,
    units    = units,
    device   = grDevices::cairo_pdf,
    limitsize = FALSE
  )
  message_time("Saved figure: ", file)
  invisible(file)
}

get_logfc_col <- function(marker_df) {
  candidates <- c("avg_log2FC", "avg_logFC")
  hit <- candidates[candidates %in% colnames(marker_df)][1]
  if (is.na(hit)) stop("No avg_log2FC/avg_logFC column found in marker table.")
  hit
}

normalize_diagnosis_group <- function(obj) {
  meta_cols <- colnames(obj@meta.data)

  if ("Diagnosis" %in% meta_cols) {
    grp <- trimws(as.character(obj$Diagnosis))
  } else if ("samp.Diagnosis" %in% meta_cols) {
    grp <- trimws(as.character(obj$`samp.Diagnosis`))
  } else if ("GROUP" %in% meta_cols) {
    grp <- trimws(as.character(obj$GROUP))
  } else if ("group" %in% meta_cols) {
    grp <- trimws(as.character(obj$group))
  } else {
    message_time("No diagnosis/group column found. Group normalization skipped.")
    return(obj)
  }

  grp_std <- rep(NA_character_, length(grp))
  grp_std[grp %in% c("Ctr", "CTR", "Ctrl", "CTRL", "Control", "CONTROL", "control", "Healthy", "HC")] <- "CTR"
  grp_std[grp %in% c("Scz", "SCZ", "Case", "CASE", "case", "Schizophrenia", "schizophrenia")] <- "SCZ"

  # Fallback for substring-based values.
  grp_lower <- tolower(grp)
  grp_std[is.na(grp_std) & grepl("ctr|ctrl|control|healthy|hc", grp_lower)] <- "CTR"
  grp_std[is.na(grp_std) & grepl("scz|schizo|case", grp_lower)] <- "SCZ"

  if (any(is.na(grp_std))) {
    warning("Some diagnosis labels could not be standardized: ",
            paste(unique(grp[is.na(grp_std)]), collapse = ", "))
  }

  obj$Group <- factor(grp_std, levels = c("CTR", "SCZ"))
  obj
}

run_harmony_safe <- function(object, dims_use, batch_col) {
  message_time("Running Harmony using batch field: ", batch_col)

  out <- tryCatch(
    harmony::RunHarmony(
      object,
      reduction      = "pca",
      group.by.vars  = batch_col,
      reduction.save = "harmony",
      dims.use       = dims_use,
      verbose        = FALSE
    ),
    error = function(e) {
      stop("harmony::RunHarmony failed: ", e$message, call. = FALSE)
    }
  )

  if (!"harmony" %in% names(out@reductions)) {
    stop("Harmony reduction was not found after RunHarmony().")
  }
  out
}

find_markers_for_clusters <- function(object, cluster_ids) {
  markers_list <- setNames(vector("list", length(cluster_ids)), paste0("Cluster_", cluster_ids))

  for (cl in cluster_ids) {
    message_time("Finding markers for cluster: ", cl)
    markers_list[[paste0("Cluster_", cl)]] <- tryCatch({
      mk <- FindMarkers(
        object,
        ident.1 = cl,
        test.use = "wilcox",
        min.pct = 0.1,
        logfc.threshold = 0.25,
        only.pos = TRUE,
        min.cells.group = 3
      )
      if (!nrow(mk)) return(data.frame())
      mk$gene    <- rownames(mk)
      mk$cluster <- cl
      logfc_col <- get_logfc_col(mk)
      mk[order(mk[[logfc_col]], decreasing = TRUE), , drop = FALSE]
    }, error = function(e) {
      message_time("Marker detection failed for cluster ", cl, ": ", e$message)
      data.frame()
    })
  }

  markers_list[sapply(markers_list, nrow) > 0]
}

write_marker_outputs <- function(markers_list, output_prefix, results_dir) {
  if (!length(markers_list)) {
    message_time("No non-empty marker tables found for prefix: ", output_prefix)
    return(invisible(NULL))
  }

  all_markers <- dplyr::bind_rows(markers_list)
  if (!nrow(all_markers)) return(invisible(NULL))

  # Full non-empty marker table.
  saveRDS(all_markers, file.path(results_dir, paste0(output_prefix, ".harmony.DE_marker.rds")))
  utils::write.csv(
    all_markers,
    file.path(results_dir, paste0(output_prefix, ".harmony.DE_marker.csv")),
    row.names = FALSE
  )

  # Significant marker sheets.
  markers_sig <- lapply(
    markers_list,
    function(df) {
      if ("p_val_adj" %in% colnames(df)) df[df$p_val_adj < 0.05, , drop = FALSE] else df
    }
  )
  markers_sig <- markers_sig[sapply(markers_sig, nrow) > 0]

  if (length(markers_sig)) {
    openxlsx::write.xlsx(
      markers_sig,
      file = file.path(results_dir, paste0(output_prefix, ".harmony.markers.xlsx")),
      asTable = TRUE
    )

    sig_counts <- sapply(markers_sig, nrow)
    utils::write.csv(
      data.frame(cluster = names(sig_counts), n_sig = as.integer(sig_counts)),
      file.path(results_dir, paste0(output_prefix, ".harmony.markers_summary.csv")),
      row.names = FALSE
    )
  }

  # Top-50 markers per cluster.
  required_cols <- c("cluster", "p_val_adj", "gene")
  if (!all(required_cols %in% colnames(all_markers))) {
    warning("Top-50 export skipped: required marker columns are missing.")
    return(invisible(all_markers))
  }

  logfc_col <- get_logfc_col(all_markers)
  top_markers <- all_markers %>%
    mutate(cluster = as.character(cluster)) %>%
    filter(!is.na(.data[[logfc_col]]), p_val_adj < 0.05) %>%
    group_by(cluster) %>%
    arrange(desc(.data[[logfc_col]]), .by_group = TRUE) %>%
    slice_head(n = 50) %>%
    ungroup()

  if (nrow(top_markers)) {
    top_sheets <- split(top_markers, paste0("Cluster_", top_markers$cluster))
    ord <- order(suppressWarnings(as.numeric(gsub("Cluster_", "", names(top_sheets)))))
    top_sheets <- top_sheets[ord]

    openxlsx::write.xlsx(
      top_sheets,
      file = file.path(results_dir, paste0(output_prefix, ".harmony.top50.xlsx")),
      asTable = TRUE
    )
    utils::write.csv(
      top_markers,
      file.path(results_dir, paste0(output_prefix, ".harmony.top50.csv")),
      row.names = FALSE
    )
  }

  invisible(all_markers)
}

# ------------------------------------------------------------------------------
# 3. Load QC-clean object
# ------------------------------------------------------------------------------
if (!file.exists(premerged_rds)) {
  stop("Missing merged object from Step 1: ", premerged_rds)
}

message_time("Loading QC-clean merged object: ", premerged_rds)
combined <- readRDS(premerged_rds)
stopifnot(inherits(combined, "Seurat"))
DefaultAssay(combined) <- "RNA"

# Ensure a batch field for Harmony.
if (!"sample" %in% colnames(combined@meta.data)) {
  if ("orig.ident" %in% colnames(combined@meta.data)) {
    combined$sample <- combined$orig.ident
  } else {
    stop("Need a batch field for Harmony: 'sample' or 'orig.ident'.")
  }
}
batch_field <- "sample"
combined <- normalize_diagnosis_group(combined)

message_time("Cells: ", ncol(combined), "; genes: ", nrow(combined))
message_time("Harmony batch levels: ", length(unique(combined[[batch_field, drop = TRUE]])))

# Save basic input metadata summaries.
input_summary <- data.frame(
  item  = c("input_rds", "n_genes", "n_cells", "batch_field", "n_batches", "n_features", "max_dims"),
  value = c(
    premerged_rds,
    nrow(combined),
    ncol(combined),
    batch_field,
    length(unique(combined[[batch_field, drop = TRUE]])),
    n_features,
    max_dims
  ),
  stringsAsFactors = FALSE
)
utils::write.csv(input_summary, file.path(results_dir, "step2_input_summary.csv"), row.names = FALSE)

if ("Group" %in% colnames(combined@meta.data)) {
  utils::write.csv(
    as.data.frame(table(combined$Group, useNA = "ifany")),
    file.path(results_dir, "step2_group_counts.csv"),
    row.names = FALSE
  )
}

# ------------------------------------------------------------------------------
# 4. Pre-processing and Harmony integration
# ------------------------------------------------------------------------------
message_time("Pre-processing: NormalizeData -> FindVariableFeatures -> ScaleData -> RunPCA")
combined <- NormalizeData(combined, verbose = FALSE)
combined <- FindVariableFeatures(
  combined,
  selection.method = "vst",
  nfeatures = n_features,
  verbose = FALSE
)
combined <- ScaleData(combined, features = VariableFeatures(combined), verbose = FALSE)
combined <- RunPCA(combined, reduction.name = "pca", npcs = max_dims, verbose = FALSE)

utils::write.csv(
  data.frame(variable_feature = VariableFeatures(combined)),
  file.path(results_dir, "step2_variable_features.csv"),
  row.names = FALSE
)

combined <- run_harmony_safe(combined, dims_use = 1:max_dims, batch_col = batch_field)

# ------------------------------------------------------------------------------
# 5. UMAP, clustering, and marker detection
# ------------------------------------------------------------------------------
run_summary <- list()

for (current_dims in n_dims_vec) {
  message_time("Processing Harmony dimensions: ", current_dims)
  set.seed(1000 + current_dims)

  umap_name  <- paste0("umap_", current_dims)
  graph_name <- paste0("RNA_snn_", current_dims)

  combined <- RunUMAP(
    combined,
    reduction = "harmony",
    dims = 1:current_dims,
    reduction.name = umap_name,
    seed.use = 123,
    verbose = FALSE
  )

  combined <- FindNeighbors(
    combined,
    reduction = "harmony",
    dims = 1:current_dims,
    graph.name = graph_name,
    verbose = FALSE
  )

  for (current_res in resolutions) {
    message_time("Clustering at resolution: ", current_res)
    set.seed(2000 + current_dims * 100 + as.integer(current_res * 100))

    combined <- FindClusters(
      combined,
      graph.name = graph_name,
      resolution = current_res,
      algorithm = 1,
      verbose = FALSE
    )

    res_tag <- as.character(current_res)
    cluster_col <- paste0("seurat_clusters_dim", current_dims, "_res", gsub("\\.", "p", res_tag))
    combined@meta.data[[cluster_col]] <- as.character(combined$seurat_clusters)
    combined@meta.data[[cluster_col]] <- factor(combined@meta.data[[cluster_col]])
    Idents(combined) <- cluster_col

    cluster_counts <- sort(table(Idents(combined)), decreasing = TRUE)
    cluster_count_df <- data.frame(
      cluster = names(cluster_counts),
      n_cells = as.integer(cluster_counts),
      stringsAsFactors = FALSE
    )
    utils::write.csv(
      cluster_count_df,
      file.path(results_dir, sprintf("dim_%d_res_%s.harmony.cluster_cell_counts.csv", current_dims, res_tag)),
      row.names = FALSE
    )

    # Vector UMAP outputs.
    p_sample <- DimPlot(
      combined,
      group.by = batch_field,
      reduction = umap_name,
      raster = FALSE
    ) + ggtitle("By sample")

    p_cluster <- DimPlot(
      combined,
      group.by = cluster_col,
      label = TRUE,
      label.size = 3,
      reduction = umap_name,
      raster = FALSE
    ) + ggtitle("By cluster")

    combined_umap <- gridExtra::grid.arrange(p_sample, p_cluster, ncol = 2)
    safe_ggsave(
      file.path(results_dir, sprintf("dim_%d_res_%s.harmony.umap.pdf", current_dims, res_tag)),
      combined_umap,
      width = 14,
      height = 7,
      units = "in"
    )

    # Save the object for this parameter combination.
    object_file <- file.path(results_dir, sprintf("dim_%d_res_%s.harmony.rds", current_dims, res_tag))
    safe_save_rds(combined, object_file)

    # Marker identification.
    valid_clusters <- names(cluster_counts[cluster_counts >= 3])
    small_clusters <- names(cluster_counts[cluster_counts < 3])

    if (length(small_clusters)) {
      warning("Skipping clusters with <3 cells: ", paste(small_clusters, collapse = ", "))
    }

    if (length(valid_clusters)) {
      markers_list <- find_markers_for_clusters(combined, valid_clusters)
      output_prefix <- sprintf("dim_%d_res_%s", current_dims, res_tag)
      write_marker_outputs(markers_list, output_prefix = output_prefix, results_dir = results_dir)
    } else {
      warning("No clusters with >=3 cells; marker detection skipped.")
    }

    run_summary[[paste(current_dims, res_tag, sep = "_")]] <- data.frame(
      dims = current_dims,
      resolution = current_res,
      n_clusters = length(cluster_counts),
      min_cluster_size = min(cluster_counts),
      max_cluster_size = max(cluster_counts),
      object_file = object_file,
      stringsAsFactors = FALSE
    )
  }
}

# ------------------------------------------------------------------------------
# 6. Final exports and reproducibility records
# ------------------------------------------------------------------------------
final_object_path <- file.path(results_dir, paste0(GROUP_name, "_harmony_final.rds"))
safe_save_rds(combined, final_object_path)

analysis_parameters <- data.frame(
  parameter = c(
    "reproduce_dir",
    "input_rds",
    "GROUP_name",
    "n_features",
    "n_dims_vec",
    "resolutions",
    "max_dims",
    "batch_field",
    "marker_test",
    "marker_min_pct",
    "marker_logfc_threshold",
    "marker_only_pos",
    "random_seed"
  ),
  value = c(
    reproduce_dir,
    premerged_rds,
    GROUP_name,
    n_features,
    paste(n_dims_vec, collapse = ","),
    paste(resolutions, collapse = ","),
    max_dims,
    batch_field,
    "wilcox",
    0.1,
    0.25,
    TRUE,
    123
  ),
  stringsAsFactors = FALSE
)
utils::write.csv(analysis_parameters, file.path(results_dir, "step2_analysis_parameters.csv"), row.names = FALSE)

if (length(run_summary)) {
  utils::write.csv(
    dplyr::bind_rows(run_summary),
    file.path(results_dir, "step2_harmony_run_summary.csv"),
    row.names = FALSE
  )
}

sink(file.path(results_dir, "sessionInfo_step2_harmony_human.txt"))
print(sessionInfo())
sink()

message_time("Human Harmony analysis completed successfully.")
message_time("Output directory: ", results_dir)
message_time("Final integrated object: ", final_object_path)
message_time("END")
